using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Adyen.Models.Enums;

namespace Adyen.Models;

public record IdealPaymentDetailsRequestProperties
{
    /// <summary>
    /// An identifier for the payment, generated by the payment method, such as iDEAL. This is obtained from the specified <c>source</c>.
    /// </summary>
    [JsonPropertyName("payload")]
    [StringLength(200, MinimumLength = 1)]
    public required string Payload { get; init; }

    [JsonPropertyName("source")]
    public required PaymentSource2 Source { get; init; }
}
